import { useQuery } from '@tanstack/react-query';

interface SearchResult {
  id: string;
  title: string;
}

async function searchRepos(query: string, signal: AbortSignal): Promise<SearchResult[]> {
  const res = await fetch(
    `https://api.github.com/search/repositories?q=${encodeURIComponent(query)}`,
    { signal } // <-- pass the AbortSignal here
  );
  if (!res.ok) throw new Error(res.statusText);
  return res.json();
}

function SearchInput() {
  const [term, setTerm] = useState('');

  const { data, isFetching } = useQuery({
    queryKey: ['search', term],
    // React Query passes the AbortSignal as the second argument
    queryFn: ({ signal }) => searchRepos(term, signal),
    // Only run when term is non-empty
    enabled: term.length > 0,
    // Keep results briefly to avoid refetching on same key
    staleTime: 30_000,
  });

  return (
    <div>
      <input
        value={term}
        onChange={(e) => setTerm(e.target.value)}
        placeholder="Search GitHub reposâ€¦"
      />
      {isFetching && <span className="fetching-indicator">Searchingâ€¦</span>}
      <ul>
        {data?.items?.map((item) => (
          <li key={item.id}><a href={item.html_url}>{item.full_name}</a></li>
        ))}
      </ul>
    </div>
  );
}

import axios from 'axios';
import { useQuery } from '@tanstack/react-query';

function useGitHubUser(username: string) {
  return useQuery({
    queryKey: ['github-user', username],
    queryFn: async ({ signal }) => {
      const { data } = await axios.get('https://api.github.com/users/' + username, {
        signal, // Axios handles AbortSignal natively
      });
      return data;
    },
    enabled: !!username,
  });
}
